// PatternCommands.js - Command Pattern Bytecode - REVISADO Gradius/R-Type
// Fix: sin teleport, sin uso de ===0 flotante, con centros relativos

const Opcode = {
  MOVE_LINEAR: 0, MOVE_SINE: 1, MOVE_CIRCLE: 2, MOVE_SPIRAL: 3, MOVE_BEZIER: 4,
  WAIT: 10, REPEAT: 11, BRANCH: 12,
  SHOOT: 20, CHANGE_SPEED: 21, CHANGE_DIRECTION: 22, SPAWN_CHILD: 23,
  SET_STATE: 30, END: 255
};

class PatternCommand {
  execute(enemy, context, dt) { throw new Error('Execute debe ser implementado'); }
  isComplete(enemy, context) { return true; }
}

class MoveLinearCommand extends PatternCommand {
  constructor(vx, vy, duration = null) { super(); this.vx=vx; this.vy=vy; this.duration=duration; this.elapsed=0; }
  execute(enemy, context, dt){ enemy.x+=this.vx*dt; enemy.y+=this.vy*dt; if(this.duration!==null) {this.elapsed+=dt;} }
  isComplete(){ return this.duration!==null && this.elapsed>=this.duration; }
}

class MoveSineCommand extends PatternCommand {
  constructor(amplitude, frequency, baseVx, duration=null){
    super(); this.amplitude=amplitude; this.frequency=frequency; this.baseVx=baseVx; this.duration=duration; this.elapsed=0; this._started=false; this.startY=0;
  }
  execute(enemy, context, dt){
    if(!this._started){ this.startY=enemy.y; this._started=true; }
    enemy.x+=this.baseVx*dt;
    enemy.y=this.startY + Math.sin(this.elapsed*this.frequency)*this.amplitude;
    this.elapsed+=dt;
  }
  isComplete(){ return this.duration!==null && this.elapsed>=this.duration; }
}

class MoveCircleCommand extends PatternCommand {
  constructor(radius, angularSpeed, centerX, centerY, duration=null){
    super(); this.radius=radius; this.angularSpeed=angularSpeed; this.centerX=centerX; this.centerY=centerY; this.duration=duration; this.elapsed=0; this._started=false; this.startAngle=0; this._relCenter=false;
  }
  execute(enemy, context, dt){
    if(!this._started){
      // si center parece fijo 320,240 y enemigo lejos -> usar centro relativo
      const dist = Math.hypot(enemy.x-this.centerX, enemy.y-this.centerY);
      if(dist > this.radius*2.5){ this.centerX = enemy.x; this.centerY = enemy.y; this._relCenter=true; }
      this.startAngle = Math.atan2(enemy.y-this.centerY, enemy.x-this.centerX);
      this._started=true;
    }
    const angle=this.startAngle+this.elapsed*this.angularSpeed;
    enemy.x=this.centerX+Math.cos(angle)*this.radius;
    enemy.y=this.centerY+Math.sin(angle)*this.radius;
    this.elapsed+=dt;
  }
  isComplete(){ return this.duration!==null && this.elapsed>=this.duration; }
}

class MoveSpiralCommand extends PatternCommand {
  constructor(initialRadius, radiusGrowth, angularSpeed, centerX, centerY, duration=null){
    super(); this.initialRadius=initialRadius; this.radiusGrowth=radiusGrowth; this.angularSpeed=angularSpeed; this.centerX=centerX; this.centerY=centerY; this.duration=duration; this.elapsed=0; this._started=false; this.startAngle=0;
  }
  execute(enemy, context, dt){
    if(!this._started){ 
      const dist=Math.hypot(enemy.x-this.centerX, enemy.y-this.centerY);
      if(dist>this.initialRadius*3){ this.centerX=enemy.x; this.centerY=enemy.y; }
      this.startAngle=Math.atan2(enemy.y-this.centerY, enemy.x-this.centerX); this._started=true;
    }
    const curR=this.initialRadius+this.elapsed*this.radiusGrowth;
    const angle=this.startAngle+this.elapsed*this.angularSpeed;
    enemy.x=this.centerX+Math.cos(angle)*curR;
    enemy.y=this.centerY+Math.sin(angle)*curR;
    this.elapsed+=dt;
  }
  isComplete(){ return this.duration!==null && this.elapsed>=this.duration; }
}

class MoveBezierCommand extends PatternCommand {
  constructor(controlPoints, duration){ super(); this.controlPoints=controlPoints; this.duration=duration; this.elapsed=0; this._started=false; this.startPos={x:0,y:0}; }
  execute(enemy, context, dt){
    if(!this._started){ this.startPos={x:enemy.x,y:enemy.y}; this._started=true; }
    const t=Math.min(1,this.elapsed/this.duration);
    const pos=this.calculateBezierPoint(t,this.controlPoints);
    enemy.x=this.startPos.x+pos.x;
    enemy.y=this.startPos.y+pos.y;
    this.elapsed+=dt;
  }
  calculateBezierPoint(t, points){
    if(points.length===4){
      const [p0,p1,p2,p3]=points; const mt=1-t, mt2=mt*mt, mt3=mt2*mt, t2=t*t, t3=t2*t;
      return { x:mt3*p0.x+3*mt2*t*p1.x+3*mt*t2*p2.x+t3*p3.x, y:mt3*p0.y+3*mt2*t*p1.y+3*mt*t2*p2.y+t3*p3.y };
    }
    if(points.length>=2){
      const idx=Math.floor(t*(points.length-1)); const nextIdx=Math.min(idx+1, points.length-1); const localT=(t*(points.length-1))-idx;
      return { x:points[idx].x+(points[nextIdx].x-points[idx].x)*localT, y:points[idx].y+(points[nextIdx].y-points[idx].y)*localT };
    }
    return {x:0,y:0};
  }
  isComplete(){ return this.elapsed>=this.duration; }
}

class WaitCommand extends PatternCommand {
  constructor(duration){ super(); this.duration=duration; this.elapsed=0; }
  execute(e,c,dt){ this.elapsed+=dt; }
  isComplete(){ return this.elapsed>=this.duration; }
}

class ShootCommand extends PatternCommand {
  constructor(direction,speed,count=1,interval=0.1){ super(); this.direction=direction; this.speed=speed; this.count=count; this.interval=interval; this.fired=0; this.lastFire=0; }
  execute(enemy, context, dt){
    this.lastFire+=dt;
    if(this.fired<this.count && this.lastFire>=this.interval){
      context.spawnProjectile(enemy.x+enemy.w/2, enemy.y+enemy.h/2, this.direction.x*this.speed, this.direction.y*this.speed);
      this.fired++; this.lastFire=0;
    }
  }
  isComplete(){ return this.fired>=this.count; }
}

class ChangeSpeedCommand extends PatternCommand {
  constructor(newVx,newVy){ super(); this.newVx=newVx; this.newVy=newVy; this.executed=false; }
  execute(enemy,c,dt){ if(!this.executed){ enemy.vx=this.newVx; enemy.vy=this.newVy; this.executed=true; } }
  isComplete(){ return this.executed; }
}

class ChangeDirectionCommand extends PatternCommand {
  constructor(angleDegrees){ super(); this.angleRadians=angleDegrees*(Math.PI/180); this.executed=false; }
  execute(enemy,c,dt){ if(!this.executed){ const s=Math.hypot(enemy.vx,enemy.vy)||120; enemy.vx=Math.cos(this.angleRadians)*s; enemy.vy=Math.sin(this.angleRadians)*s; this.executed=true; } }
  isComplete(){ return this.executed; }
}

// ── Comandos avanzados INTERCEPTOR corregidos ──
class PursueTargetCommand extends PatternCommand {
  constructor(speed, turnRate, duration){ super(); this.speed=speed; this.turnRate=turnRate; this.duration=duration; this.elapsed=0; }
  execute(enemy, context, dt){
    const target=context.getTargetPosition();
    const dx=target.x-enemy.x, dy=target.y-enemy.y;
    const dist=Math.hypot(dx,dy);
    if(dist>1){
      const desiredAngle=Math.atan2(dy,dx);
      const curAngle=Math.atan2(enemy.vy||-1, enemy.vx||-1);
      const diff=this.normalizeAngle(desiredAngle-curAngle);
      const maxTurn=this.turnRate*dt;
      const newAngle=curAngle+Math.max(-maxTurn, Math.min(maxTurn, diff));
      enemy.vx=Math.cos(newAngle)*this.speed;
      enemy.vy=Math.sin(newAngle)*this.speed;
    }
    enemy.x+=enemy.vx*dt; enemy.y+=enemy.vy*dt;
    this.elapsed+=dt;
  }
  normalizeAngle(a){ while(a>Math.PI) {a-=2*Math.PI;} while(a<-Math.PI) {a+=2*Math.PI;} return a; }
  isComplete(){ return this.duration!==null && this.elapsed>=this.duration; }
}

class ArcMovementCommand extends PatternCommand {
  constructor(startAngle, endAngle, radius, speed, centerX, centerY, duration){
    super(); this.startAngle=startAngle*(Math.PI/180); this.endAngle=endAngle*(Math.PI/180); this.radius=radius; this.speed=speed; this.centerX=centerX; this.centerY=centerY; this.duration=duration; this.elapsed=0; this._started=false; this.currentAngle=this.startAngle;
  }
  execute(enemy, context, dt){
    if(!this._started){
      // si centro absoluto lejos, recentrar relativo al enemigo
      const d=Math.hypot(enemy.x-this.centerX, enemy.y-this.centerY);
      if(d>this.radius*3){ this.centerX=enemy.x; this.centerY=enemy.y; }
      this.currentAngle=Math.atan2(enemy.y-this.centerY, enemy.x-this.centerX);
      this._started=true;
    }
    const angularSpeed=this.speed/this.radius;
    this.currentAngle+=angularSpeed*dt;
    enemy.x=this.centerX+Math.cos(this.currentAngle)*this.radius;
    enemy.y=this.centerY+Math.sin(this.currentAngle)*this.radius;
    this.elapsed+=dt;
  }
  isComplete(){ return this.duration!==null && this.elapsed>=this.duration; }
}

class FanAttackCommand extends PatternCommand {
  constructor(centerAngle, spreadAngle, bulletCount, bulletSpeed, interval){
    super(); this.centerAngle=centerAngle*(Math.PI/180); this.spreadAngle=spreadAngle*(Math.PI/180); this.bulletCount=bulletCount; this.bulletSpeed=bulletSpeed; this.interval=interval; this.fired=0; this.lastFire=0;
  }
  execute(enemy, context, dt){
    this.lastFire+=dt;
    if(this.fired<this.bulletCount && this.lastFire>=this.interval){
      const t=this.fired/(this.bulletCount-1||1);
      const angle=this.centerAngle+(t-0.5)*this.spreadAngle;
      context.spawnProjectile(enemy.x+enemy.w/2, enemy.y+enemy.h/2, Math.cos(angle)*this.bulletSpeed, Math.sin(angle)*this.bulletSpeed);
      this.fired++; this.lastFire=0;
    }
  }
  isComplete(){ return this.fired>=this.bulletCount; }
}

class ZigzagBezierCommand extends PatternCommand {
  // ahora interpreta controlPoints como OFFSETS relativos al startPos, no absolutos
  constructor(controlPoints, speed, duration){ super(); this.controlPoints=controlPoints; this.speed=speed; this.duration=duration; this.elapsed=0; this._started=false; this.startPos={x:0,y:0}; this._isAbsolute=false; }
  execute(enemy, context, dt){
    if(!this._started){
      this.startPos={x:enemy.x,y:enemy.y};
      // detectar si puntos son absolutos (x > 400) -> convertir a deltas
      if(this.controlPoints.length>0 && this.controlPoints[0].x>300 && Math.abs(this.controlPoints[0].x-enemy.x)>200){
        this._isAbsolute=true;
      }
      this._started=true;
    }
    this.elapsed+=dt;
    const t=Math.min(1,this.elapsed/this.duration);
    if(this._isAbsolute){
      // interpolar entre puntos absolutos
      const idx=Math.floor(t*(this.controlPoints.length-1));
      const n=Math.min(idx+1,this.controlPoints.length-1);
      const localT=(t*(this.controlPoints.length-1))-idx;
      const p0=this.controlPoints[idx], p1=this.controlPoints[n];
      enemy.x= p0.x+(p1.x-p0.x)*localT;
      enemy.y= p0.y+(p1.y-p0.y)*localT;
    } else {
      // offsets relativos: enemy se mueve -speed*dt en X + lerp Y entre offsets
      const pts=this.controlPoints;
      const segT=t*(pts.length-1);
      const idx=Math.min(Math.floor(segT), pts.length-2);
      const frac=segT-idx;
      const p0=pts[idx], p1=pts[idx+1];
      const offX=p0.x+(p1.x-p0.x)*frac;
      const offY=p0.y+(p1.y-p0.y)*frac;
      // mantener progresión izquierda
      enemy.x=this.startPos.x - this.speed*this.elapsed + offX;
      enemy.y=this.startPos.y + offY;
    }
  }
  distance(p1,p2){ return Math.hypot(p2.x-p1.x,p2.y-p1.y); }
  isComplete(){ return this.elapsed>=this.duration; }
}

class RetreatCommand extends PatternCommand {
  constructor(distance,speed,duration){ super(); this.distance=distance; this.speed=speed; this.duration=duration; this.elapsed=0; this.startX=0; this._started=false; }
  execute(enemy,c,dt){ if(!this._started){ this.startX=enemy.x; this._started=true; } enemy.x-=this.speed*dt; this.elapsed+=dt; }
  isComplete(enemy){ return this.elapsed>=this.duration || (this.startX-enemy.x)>=this.distance; }
}

// ── Comandos mejorados para patrones de entrada/retirada ────────────────────────

class EntranceBezierCommand extends PatternCommand {
  // Entrada suave desde la derecha con curva Bézier hacia posición de combate
  constructor(targetY, curveDepth, duration){ 
    super(); 
    this.targetY=targetY; 
    this.curveDepth=curveDepth; // Profundidad de la curva (cuánto se acerca al centro)
    this.duration=duration; 
    this.elapsed=0; 
    this._started=false; 
    this.startPos={x:0,y:0};
  }
  execute(enemy, context, dt){
    if(!this._started){ 
      this.startPos={x:enemy.x,y:enemy.y}; 
      this._started=true; 
    }
    const t=Math.min(1,this.elapsed/this.duration);
    // Curva Bézier cúbica: entrada desde derecha -> curva hacia centro -> posición target
    const p0=this.startPos;
    const p1={x:this.startPos.x-this.curveDepth,y:this.startPos.y};
    const p2={x:400,y:this.targetY}; // Punto central de pantalla
    const p3={x:350,y:this.targetY}; // Posición final de combate
    
    const mt=1-t, mt2=mt*mt, mt3=mt2*mt, t2=t*t, t3=t2*t;
    enemy.x=mt3*p0.x+3*mt2*t*p1.x+3*mt*t2*p2.x+t3*p3.x;
    enemy.y=mt3*p0.y+3*mt2*t*p1.y+3*mt*t2*p2.y+t3*p3.y;
    this.elapsed+=dt;
  }
  isComplete(){ return this.elapsed>=this.duration; }
}

class RetreatBezierCommand extends PatternCommand {
  // Retirada suave hacia la derecha con curva Bézier
  constructor(exitY, curveHeight, duration){ 
    super(); 
    this.exitY=exitY; 
    this.curveHeight=curveHeight; // Altura de la curva de retirada
    this.duration=duration; 
    this.elapsed=0; 
    this._started=false; 
    this.startPos={x:0,y:0};
  }
  execute(enemy, context, dt){
    if(!this._started){ 
      this.startPos={x:enemy.x,y:enemy.y}; 
      this._started=true; 
    }
    const t=Math.min(1,this.elapsed/this.duration);
    // Curva Bézier cúbica: posición actual -> curva hacia arriba/abajo -> salida derecha
    const p0=this.startPos;
    const p1={x:this.startPos.x-50,y:this.startPos.y};
    const p2={x:500,y:this.exitY+this.curveHeight};
    const p3={x:700,y:this.exitY}; // Posición final fuera de pantalla
    
    const mt=1-t, mt2=mt*mt, mt3=mt2*mt, t2=t*t, t3=t2*t;
    enemy.x=mt3*p0.x+3*mt2*t*p1.x+3*mt*t2*p2.x+t3*p3.x;
    enemy.y=mt3*p0.y+3*mt2*t*p1.y+3*mt*t2*p2.y+t3*p3.y;
    this.elapsed+=dt;
  }
  isComplete(){ return this.elapsed>=this.duration; }
}

class LoopDeLoopCommand extends PatternCommand {
  // Patrón de bucle clásico de Gradius: entrada -> bucle -> salida
  constructor(loopRadius, loopSpeed, duration){ 
    super(); 
    this.loopRadius=loopRadius; 
    this.loopSpeed=loopSpeed; 
    this.duration=duration; 
    this.elapsed=0; 
    this._started=false; 
    this.centerX=0;
    this.centerY=0;
    this.startAngle=0;
  }
  execute(enemy, context, dt){
    if(!this._started){ 
      this.centerX=enemy.x-this.loopRadius; 
      this.centerY=enemy.y; 
      this.startAngle=Math.PI; // Empezar desde la izquierda del círculo
      this._started=true; 
    }
    
    // Movimiento lineal hacia adelante mientras hace el bucle
    enemy.x -= 80 * dt;
    
    // Movimiento circular superpuesto
    const angle=this.startAngle+this.elapsed*this.loopSpeed;
    const loopX=Math.cos(angle)*this.loopRadius;
    const loopY=Math.sin(angle)*this.loopRadius;
    
    enemy.y=this.centerY+loopY;
    this.elapsed+=dt;
  }
  isComplete(){ return this.elapsed>=this.duration; }
}

// ── Curvas Bézier Predefinidas para Patrones Clásicos ──────────────────────────

const BezierPresets = {
  // Patrón de entrada suave desde arriba
  swoopFromTop: [
    {x: 700, y: -50},   // Start (fuera de pantalla arriba)
    {x: 500, y: 100},   // Control 1
    {x: 400, y: 200},   // Control 2
    {x: 300, y: 240}    // End (posición de combate)
  ],
  
  // Patrón de entrada suave desde abajo
  swoopFromBottom: [
    {x: 700, y: 530},   // Start (fuera de pantalla abajo)
    {x: 500, y: 380},   // Control 1
    {x: 400, y: 280},   // Control 2
    {x: 300, y: 240}    // End (posición de combate)
  ],
  
  // Patrón de entrada en Z (zigzag horizontal)
  zigzagEntry: [
    {x: 700, y: 240},   // Start
    {x: 550, y: 150},   // Control 1 (arriba)
    {x: 450, y: 330},   // Control 2 (abajo)
    {x: 300, y: 240}    // End (centro)
  ],
  
  // Patrón de retirada en S
  sCurveRetreat: [
    {x: 300, y: 240},   // Start
    {x: 400, y: 150},   // Control 1
    {x: 500, y: 330},   // Control 2
    {x: 700, y: 240}    // End (fuera de pantalla)
  ],
  
  // Patrón de bucle de Gradius
  gradiusLoop: [
    {x: 700, y: 240},   // Start
    {x: 500, y: 100},   // Control 1 (arriba del bucle)
    {x: 300, y: 380},   // Control 2 (abajo del bucle)
    {x: 100, y: 240}    // End (completar el bucle)
  ],
  
  // Patrón de espiral de entrada
  spiralEntry: [
    {x: 700, y: 240},   // Start
    {x: 600, y: 180},   // Control 1
    {x: 500, y: 300},   // Control 2
    {x: 400, y: 240},   // Control 3
    {x: 350, y: 200},   // Control 4
    {x: 300, y: 240}    // End
  ]
};

// Función helper para obtener preset y crear comando
function createBezierFromPreset(presetName, duration = 2.0) {
  const points = BezierPresets[presetName];
  if (!points) {
    console.warn(`Bezier preset not found: ${presetName}`);
    return new MoveBezierCommand([{x:0,y:0}], duration);
  }
  return new MoveBezierCommand(points, duration);
}

class PatternInterpreter {
  constructor(){ this.commands=[]; this.currentCommand=0; this.context=null; }
  loadCommands(cmds){ this.commands=cmds; this.currentCommand=0; }
  setContext(ctx){ this.context=ctx; }
  execute(enemy, dt){
    if(this.currentCommand>=this.commands.length) {return false;}
    const cmd=this.commands[this.currentCommand];
    cmd.execute(enemy,this.context,dt);
    if(cmd.isComplete(enemy,this.context)) {this.currentCommand++;}
    return true;
  }
  reset(){
    this.currentCommand=0;
    for(const c of this.commands){ if(c.elapsed!==undefined) {c.elapsed=0;} if(c.executed!==undefined) {c.executed=false;} if(c.fired!==undefined){ c.fired=0; c.lastFire=0; } if(c._started!==undefined) {c._started=false;} if(c.segment!==undefined){ c.segment=0; c.segmentProgress=0; } }
  }
  isComplete(){ return this.currentCommand>=this.commands.length; }
}

class PatternFactory {
  static createSinePattern(a,f,vx,d){ return [new MoveSineCommand(a,f,vx,d)]; }
  static createCirclePattern(r,av,cx,cy,d){ return [new MoveCircleCommand(r,av,cx,cy,d)]; }
  static createSpiralPattern(ir,rg,av,cx,cy,d){ return [new MoveSpiralCommand(ir,rg,av,cx,cy,d)]; }
  static createBezierPattern(pts,d){ return [new MoveBezierCommand(pts,d)]; }
  static createAttackPattern(vx,vy,iv,bc){ return [new MoveLinearCommand(vx,vy,null), new ShootCommand({x:-1,y:0},400,bc,iv)]; }
  static createComplexPattern(){
    return [ new MoveLinearCommand(-150,0,1.0), new WaitCommand(0.5), new ChangeDirectionCommand(-45), new MoveLinearCommand(-120,0,1.5), new ShootCommand({x:-1,y:0.3},350,3,0.15), new ChangeDirectionCommand(45), new MoveLinearCommand(-100,0,2.0) ];
  }
  static createInterceptorPattern(){
    return [
      new MoveLinearCommand(-190,0,0.9),
      new PursueTargetCommand(170, 2.2, 0.9),
      new WaitCommand(0.15),
      new FanAttackCommand(180, 55, 3, 340, 0.13),
      new MoveLinearCommand(-140,0,0.6),
      new ShootCommand({x:-1,y:0}, 420, 2, 0.14),
      new MoveLinearCommand(-260,0,1.1)
    ];
  }
  static createInterceptorSquadronPattern(){
    return [
      new MoveLinearCommand(-170,0,0.7),
      new WaitCommand(0.25),
      new ShootCommand({x:-1,y:0}, 360, 2, 0.16),
      new MoveLinearCommand(-150,0,0.6),
      new FanAttackCommand(180, 70, 3, 360, 0.12),
      new MoveLinearCommand(-220,0,1.0)
    ];
  }
  
  // Patrones mejorados de entrada/retirada
  static createEntrancePattern(targetY, curveDepth, duration){
    return [new EntranceBezierCommand(targetY, curveDepth, duration)];
  }
  
  static createRetreatPattern(exitY, curveHeight, duration){
    return [new RetreatBezierCommand(exitY, curveHeight, duration)];
  }
  
  static createLoopPattern(loopRadius, loopSpeed, duration){
    return [new LoopDeLoopCommand(loopRadius, loopSpeed, duration)];
  }
  
  // Patrones usando presets de Bézier
  static createSwoopFromTop(duration = 2.0){
    return [createBezierFromPreset('swoopFromTop', duration)];
  }
  
  static createSwoopFromBottom(duration = 2.0){
    return [createBezierFromPreset('swoopFromBottom', duration)];
  }
  
  static createZigzagEntry(duration = 2.5){
    return [createBezierFromPreset('zigzagEntry', duration)];
  }
  
  static createGradiusLoop(duration = 3.0){
    return [createBezierFromPreset('gradiusLoop', duration)];
  }
  
  static createSpiralEntry(duration = 2.5){
    return [createBezierFromPreset('spiralEntry', duration)];
  }
  
  // Patrón completo de entrada-combate-retirada
  static createFullCombatPattern(targetY, combatDuration = 2.0){
    return [
      new EntranceBezierCommand(targetY, 150, 1.5),
      new WaitCommand(combatDuration),
      new RetreatBezierCommand(targetY, 100, 1.5)
    ];
  }
}

export {
  Opcode, PatternCommand, PatternInterpreter, PatternFactory,
  MoveLinearCommand, MoveSineCommand, MoveCircleCommand,
  MoveSpiralCommand, MoveBezierCommand, WaitCommand,
  ShootCommand, ChangeSpeedCommand, ChangeDirectionCommand,
  PursueTargetCommand, ArcMovementCommand, FanAttackCommand,
  ZigzagBezierCommand, RetreatCommand,
  EntranceBezierCommand, RetreatBezierCommand, LoopDeLoopCommand,
  BezierPresets, createBezierFromPreset
};
