// SDK.js - Administra la integración con el SDK de anuncios y monetización.
export class SDKManager {
  constructor(options = {}) {
    this.gameId = options.gameId || null;
    this.ready = false;
    this.paused = false;
    this._queue = [];
    this._onPause = options.onPause || (() => {});
    this._onResume = options.onResume || (() => {});
    this.debug = !!options.debug;
    this._lastAdTime = 0;
    this._adCooldown = 30000;
    this._adPlacement = null;
    this._gdprConsent = false;
    this._consentChecked = false;

    // Suprime advertencias no críticas de anuncios sin disponibilidad en la consola.
    try {
      window.addEventListener('error', (e) => {
        const msg = String(e.message || e.error?.message || '');
        const stack = String(e.error?.stack || '');
        if (msg.includes('WX') || stack.includes('ima3') || msg.includes('VAST') || stack.includes('VAST')) {
          e.preventDefault();
          if (this.debug) {console.warn('[PALUGO SDK] VAST silenciado:', msg);}
          return true;
        }
      });
      window.addEventListener('unhandledrejection', (e) => {
        const msg = String(e.reason?.message || e.reason || '');
        if (msg.includes('WX') || msg.includes('VAST') || String(e.reason?.stack||'').includes('ima3')) {
          e.preventDefault();
        }
      });
    } catch {}

    if (options.autoInit !== false) {this.init();}
  }

  init() {
    // Check GDPR consent from localStorage
    try {
      const consent = localStorage.getItem('palugo_gdpr_consent');
      this._gdprConsent = consent === 'true';
      this._consentChecked = true;
    } catch {}

    if (!this.gameId || this.gameId.includes('YOUR_GAMEMONETIZE') || this.gameId === 'Demo') {
      if (this.debug) {console.warn('PALUGO SDK: gameId no configurado (Demo), ads deshabilitados.');}
      this.ready = true;
      return;
    }
    if (window.sdk) { this.ready = true; return; }

    window.SDK_OPTIONS = {
      gameId: this.gameId,
      onEvent: (event) => this._handleEvent(event)
    };
    if (document.getElementById('gamemonetize-sdk')) {return;}
    const script = document.createElement('script');
    script.id = 'gamemonetize-sdk';
    script.src = 'https://api.gamemonetize.com/sdk.js';
    script.async = true;
    script.onload = () => { if (this.debug) {console.log('PALUGO SDK loaded', this.gameId);} };
    script.onerror = () => console.warn('PALUGO SDK: fallo al cargar sdk.js');
    const first = document.getElementsByTagName('script')[0];
    if (first && first.parentNode) {first.parentNode.insertBefore(script, first);}
    else {document.head.appendChild(script);}

    setTimeout(() => { if (!this.ready) { this.ready = true; this._flushQueue(); } }, 5000);
  }

  _handleEvent(event) {
    console.log('[PALUGO SDK] Event received:', event);
    const name = event && (event.name || event.type || '');
    switch (name) {
      case 'SDK_READY':
        this.ready = true;
        this._flushQueue();
        break;
      case 'SDK_GAME_PAUSE':
        console.log('[PALUGO SDK] SDK_GAME_PAUSE detected - pausing');
        this.paused = true;
        this._onPause(this._adPlacement);
        break;
      case 'SDK_GAME_START':
        console.log('[PALUGO SDK] SDK_GAME_START detected - resuming');
        this.paused = false;
        this._onResume(this._adPlacement);
        if (this._adPlacement === 'rewarded_continue') {
          this._onRewardedComplete?.();
        }
        break;
      case 'SDK_BANNER_DISMISSED':
        console.log('[PALUGO SDK] SDK_BANNER_DISMISSED detected - resuming');
        this.paused = false;
        this._onResume(this._adPlacement);
        break;
      case 'SDK_REWARDED_WATCH_COMPLETE':
        console.log('[PALUGO SDK] SDK_REWARDED_WATCH_COMPLETE detected - resuming');
        this.paused = false;
        this._onResume(this._adPlacement);
        if (this._adPlacement === 'rewarded_continue') {
          this._onRewardedComplete?.();
        }
        break;
      case 'SDK_ERROR':
      case 'adLoadError':
      case 'adError':
        console.warn('[PALUGO SDK] Error event:', event);
        this.paused = false;
        this._onResume(this._adPlacement);
        break;
      default:
        console.log('[PALUGO SDK] Unknown event:', name, event);
        break;
    }
  }

  _flushQueue() {
    while (this._queue.length) {
      const fn = this._queue.shift();
      try { fn(); } catch(e){ console.warn(e); }
    }
  }

  _whenReady(fn) {
    if (this.ready) {fn();}
    else {this._queue.push(fn);}
  }

  forceResume() {
    clearTimeout(this._pauseWatchdog);
    this.paused = false;
    try { this._onResume(this._adPlacement); } catch {}
  }

  // GDPR Consent Management
  setGDPConsent(consent) {
    this._gdprConsent = consent;
    this._consentChecked = true;
    try { localStorage.setItem('palugo_gdpr_consent', consent.toString()); } catch {}
    if (this.debug) {console.log('PALUGO SDK: GDPR consent', consent);}
  }

  hasGDPConsent() {
    return this._gdprConsent;
  }

  needsGDPRPrompt() {
    if (!this.gameId || this.gameId.includes('YOUR_GAMEMONETIZE') || this.gameId === 'Demo') {
      return false;
    }
    return !this._consentChecked;
  }

  // Submit score to GameMonetize leaderboard
  submitScore(score) {
    if (!this.ready) { return; }
    try {
      if (window.sdk && typeof window.sdk.submitScore === 'function') {
        window.sdk.submitScore(score);
        if (this.debug) {console.log('PALUGO SDK: Score submitted', score);}
      }
    } catch (e) { console.warn('submitScore error', e); }
  }

  // Show GameMonetize leaderboard
  showLeaderboard() {
    if (!this.ready) { return; }
    try {
      if (window.sdk && typeof window.sdk.showLeaderboard === 'function') {
        window.sdk.showLeaderboard();
        if (this.debug) {console.log('PALUGO SDK: Show leaderboard');}
      }
    } catch (e) { console.warn('showLeaderboard error', e); }
  }

  // Show interstitial with placement tracking
  showInterstitial({ onClose, onError, placement = 'default' } = {}) {
    this._adPlacement = placement;
    let closed = false;
    const safeClose = () => {
      if (closed) {return;}
      closed = true;
      this.forceResume();
      try { onClose?.(placement); } catch {}
    };

    const now = Date.now();
    if (this._lastAdTime && (now - this._lastAdTime < this._adCooldown)) {
      if (this.debug) {console.log('PALUGO SDK: Ad cooldown, skipping', placement);}
      safeClose();
      return;
    }
    this._lastAdTime = now;

    const timer = setTimeout(safeClose, 1800);

    this._whenReady(() => {
      try {
        if (window.sdk && typeof window.sdk.showBanner === 'function') {
          window.sdk.showBanner();
          safeClose();
        } else if (typeof window.showBanner === 'function') {
          window.showBanner();
          safeClose();
        } else {
          if (this.debug) {console.log('[MOCK AD] Interstitial', placement);}
          safeClose();
        }
      } catch (e) {
        console.warn('showInterstitial error', e);
        try { onError?.(e); } catch {}
        safeClose();
      } finally {
        clearTimeout(timer);
      }
    });
  }

  // Show rewarded ad with placement tracking
  showRewarded({ onRewarded, onClose, onError, placement = 'rewarded' } = {}) {
    this._adPlacement = placement;
    let handled = false;
    const safeEnd = () => {
      if (handled) {return;}
      handled = true;
      this.forceResume();
      try { onRewarded?.(placement); } catch {}
      try { onClose?.(placement); } catch {}
    };

    const timer = setTimeout(safeEnd, 2000);

    this._whenReady(() => {
      try {
        if (window.sdk && typeof window.sdk.showRewarded === 'function') {
          window.sdk.showRewarded(() => {
            clearTimeout(timer);
            safeEnd();
          });
        } else {
          if (this.debug) {console.log('[MOCK AD] Rewarded', placement);}
          setTimeout(() => {
            clearTimeout(timer);
            safeEnd();
          }, 300);
        }
      } catch (e) {
        console.warn('showRewarded error', e);
        try { onError?.(e); } catch {}
        safeEnd();
      }
    });
  }

  // Set callback for rewarded completion (used for continue)
  onRewardedComplete(callback) {
    this._onRewardedComplete = callback;
  }

  showBanner(...args) { return this.showInterstitial(...args); }
}