  _handleGDPRInput(inputs) {
    if (!this._showGDPRPrompt) {return;}
    if (inputs.btnA) { this.engine.sdk.setGDPConsent(true); this._showGDPRPrompt = false; }
    if (inputs.btnB) { this.engine.sdk.setGDPConsent(false); this._showGDPRPrompt = false; }
  }

