// Palugo.js - Orquesta los subsistemas centrales de renderizado, audio, entrada y lógica.
// Proporciona el núcleo del motor desacoplado de la lógica específica del juego.
import { Display } from './Display.js';
import { Input } from './Input.js';
import { TouchControls, isSmartphone } from './TouchControls.js';
import { PalugoAudio } from './Audio.js';
import { SDKManager } from './SDK.js';
import { Palettes } from './Palettes.js';

export class Palugo {
  constructor(options = {}) {
    this.width = options.width || 640;
    this.height = options.height || 480;
    this.fps = options.fps === 30 ? 30 : 60; // Establece la tasa de actualización fija a 60 o 30 cuadros por segundo.
    this.fixedDt = 1 / this.fps;
    this.paused = false;
    this._running = false;

    // Inicializa los componentes según la configuración de visualización.
    const hasWindowElem = !!document.getElementById('palugo-window');
    const windowed = options.windowed !== undefined ? !!options.windowed : hasWindowElem;
    const isMobile = options.isMobile !== undefined ? !!options.isMobile : isSmartphone();
    const enableTouch = options.touchControls !== undefined ? !!options.touchControls : isMobile;
    this.display = new Display({
      width: this.width,
      height: this.height,
      palette: options.palette || Palettes.VECTOR,
      container: options.container,
      windowed,
      crt: options.crt,
      flicker: options.flicker
    });
    this.input = new Input({
      windowed
    });
    // Asigna la capa de controles táctiles si está habilitada o se detecta smartphone.
    this.touchControls = null;
    if (enableTouch) {
      this.touchControls = new TouchControls(this.input, {
        windowed,
        isMobile,
        palette: this.display.palette
      });
    }
    this.audio = new PalugoAudio({ masterVolume: options.masterVolume });
    this.sdk = new SDKManager({
      gameId: options.gameId,
      debug: options.debug,
      autoInit: options.sdk !== false,
      onPause: () => {
        console.log('[PALUGO] SDK_GAME_PAUSE - pausing game');
        this.paused = true;
      },
      onResume: () => {
        console.log('[PALUGO] SDK_GAME_START - resuming game');
        this.paused = false;
        // Give game instance invincibility for a short time after ad
        if (this.game && this.game.ship) {
          this.game.ship.iframes = 2.0; // 2 seconds of invincibility
          console.log('[PALUGO] Invincibility granted after ad');
        }
      }
    });

    // Expone referencias de compatibilidad en el objeto global.
    window.palugo = this;
    this.canvas = this.display.canvas;
    this.ctx = this.display.ctx;
    this.palette = this.display.palette;
    this.inputs = this.input.state; // Proporciona acceso directo al estado de entrada.
    this.sdkReady = false; // Indica si el SDK de publicidad se encuentra listo para operar.

    // Controla la visualización del contador de rendimiento por cuadro.
    this.showFPS = !!options.showFPS;
    this._frameCount = 0;
    this._fpsValue = this.fps;

    // Gestiona la pausa automática al cambiar la visibilidad de la pestaña.
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) {this.paused = true;}
      else if (!this.sdk.paused) {this.paused = false;}
    });
    // El sistema de audio gestiona su propio desbloqueo mediante interacción del usuario.
  }

  // ── Fachada de Renderizado ──────────────────────────────────────────
  clear(c) { this.display.clear(c); }
  drawText(...a) { return this.display.drawText(...a); }
  drawTextASCII(...a) { return this.display.drawText(...a); }
  drawSpriteASCII(...a) { return this.display.drawSpriteASCII(...a); }
  drawRect(...a) { return this.display.drawRect(...a); }
  drawCircle(...a) { return this.display.drawCircle(...a); }
  drawPixel(...a) { return this.display.drawPixel(...a); }
  drawLine(...a) { return this.display.drawLine(...a); }
  drawPoly(...a) { return this.display.drawPoly(...a); }
  drawVectorShip(...a) { return this.display.drawVectorShip(...a); }
  drawVectorEnemy(...a) { return this.display.drawVectorEnemy(...a); }
  drawVectorPlanet(...a) { return this.display.drawVectorPlanet(...a); }
  drawVectorSun(...a) { return this.display.drawVectorSun(...a); }
  drawVectorMiniboss(...a) { return this.display.drawVectorMiniboss(...a); }
  drawVectorCyclopsEgg(...a) { return this.display.drawVectorCyclopsEgg(...a); }
  drawVectorNeonSlime(...a) { return this.display.drawVectorNeonSlime(...a); }
  drawVectorSawSpinner(...a) { return this.display.drawVectorSawSpinner(...a); }
  drawMiniboss(...a) { return this.display.drawMiniboss(...a); }
  drawVectorObstacle(...a) { return this.display.drawVectorObstacle(...a); }
  isVector() { return this.display.isVector(); }
  setPalette(p) {
    this.display.setPalette(p);
    this.palette = this.display.palette;
    if (this.touchControls?.applyPalette) this.touchControls.applyPalette(this.palette);
  }
  setPalettePreset(n) {
    this.display.setPalettePreset(n);
    this.palette = this.display.palette;
    if (this.touchControls?.applyPalette) this.touchControls.applyPalette(this.palette);
  }
  getPalette() { return this.display.getPalette(); }
  measureText(...a) { return this.display.measureText(...a); }

  // ── Fachada de SDK y Servicios ──────────────────────────────────────
  showBanner(o) { return this.sdk.showInterstitial(o); }
  showInterstitial(o) { return this.sdk.showInterstitial(o); }
  showRewarded(o) { return this.sdk.showRewarded(o); }

  pause() {
    this.paused = true;
    if (this.sdk) {this.sdk.paused = true;}
  }

  resume() {
    this.paused = false;
    if (this.sdk) {this.sdk.forceResume();}
  }

  requestFullscreen() {
    try {
      const el = this.display?.container || this.display?.canvas || document.documentElement;
      if (el.requestFullscreen) { el.requestFullscreen(); }
      else if (el.webkitRequestFullscreen) { el.webkitRequestFullscreen(); }
      else if (el.msRequestFullscreen) { el.msRequestFullscreen(); }
    } catch {}
  }

  // ── Bucle de Juego con Intervalo de Tiempo Fijo ─────────────────────
  start(gameInstance) {
    if (!gameInstance || typeof gameInstance.update !== 'function' || typeof gameInstance.render !== 'function') {
      throw new Error('PALUGO: gameInstance debe implementar update(inputs, dt) y render(engine)');
    }
    if (this._running) {return;}
    this._running = true;
    this.game = gameInstance;
    // Ejecuta la inicialización opcional del juego.
    if (typeof gameInstance.init === 'function') {gameInstance.init(this);}

    let last = performance.now();
    let acc = 0;
    let fpsTimer = 0;

    const loop = (now) => {
      if (!this._running) {return;}
      requestAnimationFrame(loop);

      if (this.paused) {return;}

      let frameDt = (now - last) / 1000;
      last = now;
      // Limita el acumulador de tiempo para evitar sobrecarga tras pausas prolongadas.
      frameDt = Math.min(frameDt, 0.1);

      // Sincroniza el estado de disponibilidad del SDK.
      this.sdkReady = this.sdk.ready;

      acc += frameDt;
      fpsTimer += frameDt;
      this._frameCount++;

      // Ejecuta las actualizaciones de física y lógica a paso constante.
      let ticks = 0;
      while (acc >= this.fixedDt && ticks < 4) {
        this.input.update(this.fixedDt);
        const inputs = this.input.getState();
        this.inputs = inputs;
        this.game.update(inputs, this.fixedDt);
        this.input.flushJustPressed();
        acc -= this.fixedDt;
        ticks++;
      }

      // Renderiza un cuadro visual por cada ciclo de animación.
      this.display.clear(0);
      this.game.render(this);

      if (this.showFPS && fpsTimer >= 0.5) {
        console.log(`FPS: ${this._frameCount / fpsTimer}`);
        this._frameCount = 0;
        fpsTimer = 0;
      }
    };

    requestAnimationFrame(loop);
  }



  stop() { 
    this._running = false; 
    if (this.touchControls) {
      this.touchControls.destroy();
      this.touchControls = null;
    }
  }

  // Modifica dinámicamente la frecuencia de actualización del motor.
  setFPS(fps) {
    this.fps = fps === 30 ? 30 : 60;
    this.fixedDt = 1 / this.fps;
  }
}

// Define alias de compatibilidad con versiones previas.
export const PocketArcade = Palugo;
export const PocketArcadeEngine = Palugo;
export default Palugo;
