// GameMath.js - Proporciona cálculos matemáticos, vectoriales y curvas para el juego.
// Implementa operaciones con vectores 2D, interpolaciones, trayectorias y formaciones.
// Optimiza el cálculo de físicas y trayectorias orgánicas en tiempo real.

// ── Vector2D: Clase para operaciones vectoriales en 2D ───────────────────────
export class Vector2D {
  constructor(x = 0, y = 0) {
    this.x = x;
    this.y = y;
  }
  
  // Crear desde ángulo y magnitud
  static fromAngle(angle, magnitude = 1) {
    return new Vector2D(
      Math.cos(angle) * magnitude,
      Math.sin(angle) * magnitude
    );
  }
  
  // Retorna la suma de este vector con otro.
  add(v) {
    return new Vector2D(this.x + v.x, this.y + v.y);
  }
  
  // Retorna la resta entre este vector y otro.
  subtract(v) {
    return new Vector2D(this.x - v.x, this.y - v.y);
  }
  
  // Retorna el vector multiplicado por un valor escalar.
  multiply(scalar) {
    return new Vector2D(this.x * scalar, this.y * scalar);
  }
  
  // Retorna el vector dividido por un valor escalar.
  divide(scalar) {
    return new Vector2D(this.x / scalar, this.y / scalar);
  }
  
  // Producto punto
  dot(v) {
    return this.x * v.x + this.y * v.y;
  }
  
  // Producto cruz (2D retorna escalar z)
  cross(v) {
    return this.x * v.y - this.y * v.x;
  }
  
  // Magnitud (longitud)
  magnitude() {
    return Math.sqrt(this.x * this.x + this.y * this.y);
  }
  
  // Magnitud al cuadrado (más eficiente para comparaciones)
  magnitudeSquared() {
    return this.x * this.x + this.y * this.y;
  }
  
  // Normalizar (vector unitario)
  normalize() {
    const mag = this.magnitude();
    if (mag === 0) {return new Vector2D(0, 0);}
    return this.divide(mag);
  }
  
  // Calcula la distancia euclidiana hacia otro punto o vector.
  distanceTo(v) {
    return this.subtract(v).magnitude();
  }
  
  // Ángulo en radianes
  angle() {
    return Math.atan2(this.y, this.x);
  }
  
  // Ángulo en grados
  angleDegrees() {
    return this.angle() * (180 / Math.PI);
  }
  
  // Rotar vector
  rotate(angleRadians) {
    const cos = Math.cos(angleRadians);
    const sin = Math.sin(angleRadians);
    return new Vector2D(
      this.x * cos - this.y * sin,
      this.x * sin + this.y * cos
    );
  }
  
  // Escalar a una magnitud específica
  scaleTo(magnitude) {
    return this.normalize().multiply(magnitude);
  }
  
  // Lerp hacia otro vector
  lerp(v, t) {
    return new Vector2D(
      this.x + (v.x - this.x) * t,
      this.y + (v.y - this.y) * t
    );
  }
  
  // Retorna una copia independiente de la instancia vectorial.
  clone() {
    return new Vector2D(this.x, this.y);
  }
  
  // Convertir a string
  toString() {
    return `Vector2D(${this.x.toFixed(2)}, ${this.y.toFixed(2)})`;
  }
}

// ── Funciones de Interpolación ───────────────────────────────────────────────

// Interpolación lineal (Lerp)
export function lerp(a, b, t) {
  return a + (b - a) * t;
}

// Lerp para vectores
export function lerpVector(v1, v2, t) {
  return v1.lerp(v2, t);
}

// Lerp con clamp (t entre 0 y 1)
export function lerpClamped(a, b, t) {
  t = Math.max(0, Math.min(1, t));
  return a + (b - a) * t;
}

// Interpolación suave (Smoothstep)
export function smoothstep(t) {
  return t * t * (3 - 2 * t);
}

// Interpolación más suave (Smootherstep)
export function smootherstep(t) {
  return t * t * t * (t * (t * 6 - 15) + 10);
}

// Interpolación sinusoidal
export function sinusoidal(t) {
  return (1 - Math.cos(t * Math.PI)) / 2;
}

// ── Curvas Bézier ─────────────────────────────────────────────────────────────

// Curva Bézier lineal (2 puntos)
export function bezierLinear(p0, p1, t) {
  return new Vector2D(
    lerp(p0.x, p1.x, t),
    lerp(p0.y, p1.y, t)
  );
}

// Curva Bézier cuadrática (3 puntos)
export function bezierQuadratic(p0, p1, p2, t) {
  const mt = 1 - t;
  return new Vector2D(
    mt * mt * p0.x + 2 * mt * t * p1.x + t * t * p2.x,
    mt * mt * p0.y + 2 * mt * t * p1.y + t * t * p2.y
  );
}

// Curva Bézier cúbica (4 puntos)
export function bezierCubic(p0, p1, p2, p3, t) {
  const mt = 1 - t;
  const mt2 = mt * mt;
  const mt3 = mt2 * mt;
  const t2 = t * t;
  const t3 = t2 * t;
  
  return new Vector2D(
    mt3 * p0.x + 3 * mt2 * t * p1.x + 3 * mt * t2 * p2.x + t3 * p3.x,
    mt3 * p0.y + 3 * mt2 * t * p1.y + 3 * mt * t2 * p2.y + t3 * p3.y
  );
}

// Curva Bézier general (n puntos)
export function bezierGeneral(points, t) {
  if (points.length === 0) {return new Vector2D(0, 0);}
  if (points.length === 1) {return points[0].clone();}
  
  const result = points.map(p => p.clone());
  for (let k = 1; k < points.length; k++) {
    for (let i = 0; i < points.length - k; i++) {
      result[i] = result[i].lerp(result[i + 1], t);
    }
  }
  return result[0];
}

// Obtener puntos discretos de una curva Bézier
export function bezierPoints(points, numSegments = 20) {
  const result = [];
  for (let i = 0; i <= numSegments; i++) {
    const t = i / numSegments;
    result.push(bezierGeneral(points, t));
  }
  return result;
}

// ── Funciones Trigonométricas para Patrones ───────────────────────────────────

// Onda sinusoidal con parámetros
export function sineWave(t, amplitude, frequency, phase = 0) {
  return amplitude * Math.sin(frequency * t + phase);
}

// Calcula la posición oscilatoria según amplitud, frecuencia y fase cosenoidal. con parámetros
export function cosineWave(t, amplitude, frequency, phase = 0) {
  return amplitude * Math.cos(frequency * t + phase);
}

// Movimiento en círculo
export function circularMotion(centerX, centerY, radius, angle) {
  return new Vector2D(
    centerX + Math.cos(angle) * radius,
    centerY + Math.sin(angle) * radius
  );
}

// Calcula una trayectoria en espiral que varía su radio con el tiempo.
export function spiralMotion(centerX, centerY, initialRadius, radiusGrowth, angle) {
  const currentRadius = initialRadius + radiusGrowth * angle;
  return new Vector2D(
    centerX + Math.cos(angle) * currentRadius,
    centerY + Math.sin(angle) * currentRadius
  );
}

// Movimiento en Lissajous (figuras complejas)
export function lissajousMotion(centerX, centerY, amplitudeX, amplitudeY, freqX, freqY, phase, t) {
  return new Vector2D(
    centerX + amplitudeX * Math.sin(freqX * t + phase),
    centerY + amplitudeY * Math.sin(freqY * t)
  );
}

// ── Utilidades Matemáticas para Juego ─────────────────────────────────────────

// Normalizar ángulo a rango [-π, π]
export function normalizeAngle(angle) {
  while (angle > Math.PI) {angle -= 2 * Math.PI;}
  while (angle < -Math.PI) {angle += 2 * Math.PI;}
  return angle;
}

// Diferencia angular más corta entre dos ángulos
export function angleDifference(angle1, angle2) {
  const diff = angle2 - angle1;
  return normalizeAngle(diff);
}

// Interpolación angular (evita el problema del wrap-around)
export function lerpAngle(angle1, angle2, t) {
  const diff = angleDifference(angle1, angle2);
  return angle1 + diff * t;
}

// Conversión de grados a radianes
export function degToRad(degrees) {
  return degrees * (Math.PI / 180);
}

// Conversión de radianes a grados
export function radToDeg(radians) {
  return radians * (180 / Math.PI);
}

// Clamp de valor
export function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

// Mapeo de rango
export function mapRange(value, inMin, inMax, outMin, outMax) {
  return outMin + (value - inMin) * (outMax - outMin) / (inMax - inMin);
}

// Aleatorio en rango
export function randomRange(min, max) {
  return min + Math.random() * (max - min);
}

// Aleatorio entero en rango
export function randomInt(min, max) {
  return Math.floor(randomRange(min, max + 1));
}

// Easing functions para animaciones
export const Easing = {
  linear: t => t,
  easeInQuad: t => t * t,
  easeOutQuad: t => t * (2 - t),
  easeInOutQuad: t => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t,
  easeInCubic: t => t * t * t,
  easeOutCubic: t => (--t) * t * t + 1,
  easeInOutCubic: t => t < 0.5 ? 4 * t * t * t : (t - 1) * (2 * t - 2) * (2 * t - 2) + 1,
  easeInElastic: t => {
    const c4 = (2 * Math.PI) / 3;
    return t === 0 ? 0 : t === 1 ? 1 : -Math.pow(2, 10 * t - 10) * Math.sin((t * 10 - 10.75) * c4);
  },
  easeOutElastic: t => {
    const c4 = (2 * Math.PI) / 3;
    return t === 0 ? 0 : t === 1 ? 1 : Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * c4) + 1;
  },
  easeOutBounce: t => {
    const n1 = 7.5625;
    const d1 = 2.75;
    if (t < 1 / d1) {
      return n1 * t * t;
    } else if (t < 2 / d1) {
      return n1 * (t -= 1.5 / d1) * t + 0.75;
    } else if (t < 2.5 / d1) {
      return n1 * (t -= 2.25 / d1) * t + 0.9375;
    } else {
      return n1 * (t -= 2.625 / d1) * t + 0.984375;
    }
  }
};

// ── Sistema de coordenadas y transformaciones ─────────────────────────────────

// Transformar coordenadas locales a mundiales
export function localToWorld(localPos, origin, rotation, scale) {
  let pos = localPos.clone();
  if (scale !== 1) {pos = pos.multiply(scale);}
  if (rotation !== 0) {pos = pos.rotate(rotation);}
  return pos.add(origin);
}

// Transformar coordenadas mundiales a locales
export function worldToLocal(worldPos, origin, rotation, scale) {
  let pos = worldPos.subtract(origin);
  if (rotation !== 0) {pos = pos.rotate(-rotation);}
  if (scale !== 1) {pos = pos.divide(scale);}
  return pos;
}

// ── Física simple para colisiones ─────────────────────────────────────────────

// Distancia punto a línea
export function pointToLineDistance(point, lineStart, lineEnd) {
  const line = lineEnd.subtract(lineStart);
  const len = line.magnitude();
  if (len === 0) {return point.distanceTo(lineStart);}
  
  const t = clamp(point.subtract(lineStart).dot(line) / (len * len), 0, 1);
  const projection = lineStart.add(line.multiply(t));
  return point.distanceTo(projection);
}

// Verificar si punto está dentro de círculo
export function pointInCircle(point, circleCenter, radius) {
  return point.distanceTo(circleCenter) <= radius;
}

// Verificar si punto está dentro de rectángulo
export function pointInRect(point, rectMin, rectMax) {
  return point.x >= rectMin.x && point.x <= rectMax.x &&
         point.y >= rectMin.y && point.y <= rectMax.y;
}

// ── Generadores de patrones matemáticos ───────────────────────────────────────

// Generar puntos en formación de V (apex único, estilo Gradius)
export function vFormation(count, spread, depth) {
  const points = [];
  if (count <= 0) {return points;}
  points.push(new Vector2D(0, 0)); // punta
  for (let i = 1; i < count; i++) {
    const pair = Math.ceil(i / 2); // 1,1,2,2,3...
    const side = (i % 2 === 1) ? 1 : -1; // impar arriba, par abajo
    points.push(new Vector2D(pair * depth, side * pair * spread));
  }
  return points;
}

// Generar puntos en formación de línea
export function lineFormation(count, spacing, offset = 0) {
  const points = [];
  for (let i = 0; i < count; i++) {
    points.push(new Vector2D(i * spacing + offset, 0));
  }
  return points;
}

// Generar puntos en formación de círculo
export function circleFormation(count, radius) {
  const points = [];
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    points.push(new Vector2D(
      Math.cos(angle) * radius,
      Math.sin(angle) * radius
    ));
  }
  return points;
}

// Generar puntos en formación de grid
export function gridFormation(rows, cols, spacingX, spacingY) {
  const points = [];
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      points.push(new Vector2D(
        col * spacingX,
        row * spacingY
      ));
    }
  }
  return points;
}
